public class AVAExecuteAsynchronousController extends SysOperationServiceController
{
    AVAExecuteAsynchronouseType executeAsynchronouseType;

}

Method.Source:
private void initFromExecutionMode()
{
    this.parmShowDialog(false);
    this.parmLoadFromSysLastValue(false);

    switch (executionMode)
    {
        case SysOperationExecutionMode::ReliableAsynchronous:
            this.parmRegisterCallbackForReliableAsyncCall(false);
            break;
    }
}

protected void initializeContractFromArgs(Args _args)
{
    AVAExecuteAsynchronousContract  executeAsynchronousContract;

    executeAsynchronousContract = this.getDataContractObject();
    executeAsynchronousContract.parmCallerRecord(_args.record());
}

protected void initializeContractFromCommon(Common _common)
{
    AVAExecuteAsynchronousContract  executeAsynchronousContract;

    executeAsynchronousContract = this.getDataContractObject();
    executeAsynchronousContract.parmCallerRecord(_common);
}

public void new(IdentifierName              _className      = classStr(AVAExecuteAsynchronousService),
                IdentifierName              _methodName     =  methodStr(AVAExecuteAsynchronousService, execute),
                SysOperationExecutionMode   _executionMode  = SysOperationExecutionMode::Synchronous)
{
    super(_className, _methodName, _executionMode);
}

private AVAExecuteAsynchronouseType parmExecuteAsynchronouseType(AVAExecuteAsynchronouseType _executeAsynchronouseType = executeAsynchronouseType)
{
    executeAsynchronouseType = _executeAsynchronouseType;

    return executeAsynchronouseType;
}

protected void setContractExecuteAsynchronouseType()
{
    AVAExecuteAsynchronousContract  executeAsynchronousContract;

    executeAsynchronousContract = this.getDataContractObject();
    executeAsynchronousContract.parmExecuteAsynchronouseType(executeAsynchronouseType);
}

public static AVAExecuteAsynchronousController construct(AVAExecuteAsynchronouseType _executeAsynchronouseType, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::ReliableAsynchronous)
{
    AVAExecuteAsynchronousController controller = new AVAExecuteAsynchronousController(classStr(AVAExecuteAsynchronousService), methodStr(AVAExecuteAsynchronousService, execute), _executionMode);

    controller.parmExecuteAsynchronouseType(_executeAsynchronouseType);

    return controller;
}

public static void printAsynchronouse(Common                        _common,
                                      AVAExecuteAsynchronouseType   _executeAsynchronouseType,
                                      SysOperationExecutionMode     _executionMode              = SysOperationExecutionMode::ReliableAsynchronous)
{
    AVAExecuteAsynchronousController controller;

    controller  = AVAExecuteAsynchronousController::construct(_executeAsynchronouseType, _executionMode);

    controller.initFromExecutionMode();
    controller.initializeContractFromCommon(_common);
    controller.setContractExecuteAsynchronouseType();
    controller.parmReliableAsyncBatchGroupId(WHSParameters::find().AVAAsynchronousBatchGroupId);
    controller.startOperation();
}
